// Invisible-character highlighting — the single source shared by the app's
// `MonacoFeatureController` and the standalone `EditorStandaloneChrome`.
//
// Monaco's own `unicodeHighlight.invisibleCharacters` is deliberately kept OFF
// on every surface: it skips runs it considers "allowed", renders a zero-width
// character as a zero-width box, and cannot distinguish a line-leading ZWSP
// (which invisibly separated scripts rely on) from one mid-word. Both surfaces
// therefore draw their own decorations, reusing Monaco's `unicode-highlight`
// class so the bundled border/background styling still applies; the visual
// tweaks live in `styles/_invisible-character-highlight.scss`.

import { ZERO_WIDTH_SPACE } from './shared.ts';

/**
 * Every code point worth flagging: C0/C1 controls, the Unicode space and
 * separator blocks, and the format (`Cf`) category — ZWSP, ZWNJ, ZWJ, BOM, the
 * bidi controls, and friends.
 */
export const INVISIBLE_CHARACTER_REGEX =
  /[\u0000-\u0008\u000B-\u001F\u007F-\u009F\u00A0\u1680\u180E\u2000-\u200F\u2028-\u202F\u205F-\u206F\u3000\u3164\uFFA0\uFEFF\p{Cf}]/gu;

/** Tab, newline, and plain space: invisible, but not worth flagging. */
export const ALLOWED_INVISIBLE_CHARACTER_CODE_POINTS = new Set([9, 10, 32]);

/** Upper bound on decorations per pass, so a pathological document can't stall. */
export const MAX_INVISIBLE_CHARACTER_DECORATIONS = 5000;

export const SINGLE_INVISIBLE_CHARACTER_DECORATION_CLASS = 'unicode-highlight';
export const START_LINE_INVISIBLE_CHARACTER_DECORATION_CLASS =
  'unicode-highlight start-line';
export const MULTIPLE_INVISIBLE_CHARACTER_DECORATION_CLASS =
  'unicode-highlight unicode-highlight--multiple';
export const START_LINE_MULTIPLE_INVISIBLE_CHARACTER_DECORATION_CLASS =
  'unicode-highlight unicode-highlight--multiple start-line';

/** The decoration `description` both surfaces tag their decorations with. */
export const INVISIBLE_CHARACTER_DECORATION_DESCRIPTION =
  'open-lyric-invisible-character-highlight';

/** One highlighted run: consecutive invisible characters on a single line. */
export interface InvisibleCharacterRun {
  lineNumber: number;
  /** 1-based, Monaco column convention. */
  startColumn: number;
  endColumn: number;
  className: string;
}

/** The slice of a Monaco text model the scan needs. */
export interface InvisibleCharacterModel {
  getLineCount(): number;
  getLineContent(lineNumber: number): string;
}

/** A fresh regex per caller — `lastIndex` is per-instance state. */
export function createInvisibleCharacterRegex(): RegExp {
  return new RegExp(
    INVISIBLE_CHARACTER_REGEX.source,
    INVISIBLE_CHARACTER_REGEX.flags,
  );
}

/** Matches two or more adjacent invisible characters (what Format collapses). */
export function createDuplicateInvisibleCharacterRunRegex(): RegExp {
  return new RegExp(
    `(?:${INVISIBLE_CHARACTER_REGEX.source}){2,}`,
    INVISIBLE_CHARACTER_REGEX.flags,
  );
}

function getRunClassName(
  runLength: number,
  runStartsWithLineStartZeroWidthSpace: boolean,
): string {
  if (runLength > 1) {
    return runStartsWithLineStartZeroWidthSpace
      ? START_LINE_MULTIPLE_INVISIBLE_CHARACTER_DECORATION_CLASS
      : MULTIPLE_INVISIBLE_CHARACTER_DECORATION_CLASS;
  }

  return runStartsWithLineStartZeroWidthSpace
    ? START_LINE_INVISIBLE_CHARACTER_DECORATION_CLASS
    : SINGLE_INVISIBLE_CHARACTER_DECORATION_CLASS;
}

/**
 * Scan `model` and return one run per group of adjacent invisible characters.
 *
 * Adjacent characters merge into a single run so a stretch of them reads as one
 * block rather than a picket fence; a run of more than one gets the "multiple"
 * class (a filled warning box), and a run that starts at column 1 with a ZWSP
 * gets `start-line` so the marker isn't nudged off the left edge.
 */
export function collectInvisibleCharacterRuns(
  model: InvisibleCharacterModel,
  maxRuns: number = MAX_INVISIBLE_CHARACTER_DECORATIONS,
): InvisibleCharacterRun[] {
  const runs: InvisibleCharacterRun[] = [];
  const invisibleCharacterRegex = createInvisibleCharacterRegex();
  const lineCount = model.getLineCount();

  for (let lineNumber = 1; lineNumber <= lineCount; lineNumber += 1) {
    const lineContent = model.getLineContent(lineNumber);

    if (!lineContent) {
      continue;
    }

    invisibleCharacterRegex.lastIndex = 0;
    let match: RegExpExecArray | null;
    let runStartColumn = 0;
    let runEndColumn = 0;
    let runLength = 0;
    let runStartsWithLineStartZeroWidthSpace = false;

    const pushRun = () => {
      runs.push({
        lineNumber,
        startColumn: runStartColumn,
        endColumn: runEndColumn,
        className: getRunClassName(
          runLength,
          runStartsWithLineStartZeroWidthSpace,
        ),
      });
      return runs.length >= maxRuns;
    };

    while ((match = invisibleCharacterRegex.exec(lineContent))) {
      if (
        ALLOWED_INVISIBLE_CHARACTER_CODE_POINTS.has(
          match[0].codePointAt(0) as number,
        )
      ) {
        continue;
      }

      const startColumn = match.index + 1;
      const endColumn = match.index + match[0].length + 1;

      if (!runLength) {
        runStartColumn = startColumn;
        runEndColumn = endColumn;
        runLength = 1;
        runStartsWithLineStartZeroWidthSpace =
          startColumn === 1 && match[0] === ZERO_WIDTH_SPACE;
        continue;
      }

      if (startColumn === runEndColumn) {
        runEndColumn = endColumn;
        runLength += 1;
        continue;
      }

      if (pushRun()) {
        return runs;
      }

      runStartColumn = startColumn;
      runEndColumn = endColumn;
      runLength = 1;
      runStartsWithLineStartZeroWidthSpace =
        startColumn === 1 && match[0] === ZERO_WIDTH_SPACE;
    }

    if (!runLength) {
      continue;
    }

    if (pushRun()) {
      return runs;
    }
  }

  return runs;
}
