import {
  CONFIG_ENUM_FIELD_VALUES,
  CONFIG_FIELD_NAMES,
  CONFIG_LOCALE_VALUES,
  normalizeConfigFieldName,
  parseConfigLocaleEntries,
} from '../../../../editor/scripts/shared.ts';
import {
  DECLARE_PART_POPUP_MARGIN_PX,
  DECLARE_PART_POPUP_OFFSET_PX,
  MAX_TEMPO_BPM,
  MIN_TEMPO_BPM,
} from './constants.ts';

function applyPreviewControllerConfigPopupMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    populateDeclarePartPopup(this: any, insertIndex = null) {
      const popup = this.ensureDeclarePartPopup();
      const declaredParts = this.collectDeclaredPartEntries(
        this.getCurrentValue(),
      );
      const optionButtons = this.getStructurePartOptions(insertIndex);

      popup.replaceChildren();

      optionButtons.forEach((option) => {
        const optionButton = document.createElement('button');

        optionButton.className = 'ol-preview-config__declare-part-option';
        optionButton.type = 'button';
        optionButton.setAttribute('role', 'menuitem');
        optionButton.dataset.previewAction = 'select-structure-part';
        optionButton.dataset.partName = option.partName;
        optionButton.dataset.structureToken = option.token;
        optionButton.textContent = option.partName;
        optionButton.title = `Use ${option.partName} in Structure`;

        popup.appendChild(optionButton);
      });

      if (!optionButtons.length) {
        const emptyState = document.createElement('p');

        emptyState.className = 'ol-preview-config__declare-part-empty';
        emptyState.textContent = declaredParts.length
          ? 'No declared parts can be added here without duplicating a neighboring Structure step.'
          : 'No declared parts are available to add to Structure.';
        popup.appendChild(emptyState);
      }

      return popup;
    },

    positionDeclarePartPopup(this: any, triggerButton, popup) {
      popup.hidden = false;
      popup.style.visibility = 'hidden';
      popup.style.left = `${DECLARE_PART_POPUP_MARGIN_PX}px`;
      popup.style.top = `${DECLARE_PART_POPUP_MARGIN_PX}px`;

      const triggerRect = triggerButton.getBoundingClientRect();
      const popupRect = popup.getBoundingClientRect();
      const maxLeft = Math.max(
        DECLARE_PART_POPUP_MARGIN_PX,
        window.innerWidth - popupRect.width - DECLARE_PART_POPUP_MARGIN_PX,
      );
      const maxTop = Math.max(
        DECLARE_PART_POPUP_MARGIN_PX,
        window.innerHeight - popupRect.height - DECLARE_PART_POPUP_MARGIN_PX,
      );

      let left = Math.min(triggerRect.right - popupRect.width, maxLeft);
      let top = triggerRect.bottom + DECLARE_PART_POPUP_OFFSET_PX;

      if (top > maxTop) {
        top = triggerRect.top - popupRect.height - DECLARE_PART_POPUP_OFFSET_PX;
      }

      left = Math.max(DECLARE_PART_POPUP_MARGIN_PX, left);
      top = Math.max(DECLARE_PART_POPUP_MARGIN_PX, Math.min(top, maxTop));

      popup.style.left = `${Math.round(left)}px`;
      popup.style.top = `${Math.round(top)}px`;
      popup.style.visibility = '';
    },

    getConfigKeyOptions(this: any, currentValue = '') {
      return Array.from(
        new Set(
          [currentValue, ...(CONFIG_ENUM_FIELD_VALUES.Key || [])]
            .map((value) => String(value ?? '').trim())
            .filter(Boolean),
        ),
      );
    },

    populateConfigAttachmentPopup(this: any) {
      const popup = this.ensureConfigAttachmentPopup();
      const form = document.createElement('form');
      const label = document.createElement('label');
      const labelText = document.createElement('span');
      const input = document.createElement('input');
      const helpText = document.createElement('p');
      const actions = document.createElement('div');
      const submitButton = document.createElement('button');

      popup.replaceChildren();

      form.className = 'ol-preview-config__attachment-form';
      form.noValidate = true;

      label.className = 'ol-preview-config__attachment-label';
      labelText.className = 'ol-preview-config__attachment-label-text';
      labelText.textContent = 'Link or markdown link';
      input.className = 'ol-preview-config__attachment-input';
      input.type = 'text';
      input.placeholder = 'https://a.c/file.mp3 or [B](https://a.c/file.mp3)';
      input.autocomplete = 'off';
      input.spellcheck = false;
      input.dataset.previewAction = 'edit-config-attachment-value';
      input.setAttribute('aria-label', 'Attachment link');
      input.setAttribute('aria-invalid', 'false');
      label.append(labelText, input);

      helpText.className = 'ol-preview-config__attachment-help';
      helpText.textContent =
        'Paste a protocol URL or a markdown link such as [B](https://a.c/b.mp3).';

      actions.className = 'ol-preview-config__attachment-actions';
      submitButton.className = 'ol-preview-config__attachment-submit';
      submitButton.type = 'submit';
      submitButton.textContent = 'Add attachment';
      submitButton.disabled = true;
      actions.append(submitButton);

      form.append(label, helpText, actions);
      popup.append(form);
      return popup;
    },

    getConfigAddFieldOptions(this: any, rawValue = '') {
      return Array.from(
        new Set(
          String(rawValue ?? '')
            .split('||')
            .map((fieldName) => normalizeConfigFieldName(fieldName))
            .filter((fieldName) => CONFIG_FIELD_NAMES.includes(fieldName)),
        ),
      );
    },

    populateConfigAddPopup(this: any, rawMissingFields = '') {
      const popup = this.ensureConfigAddPopup();
      const fieldNames = this.getConfigAddFieldOptions(rawMissingFields);

      popup.replaceChildren();

      fieldNames.forEach((fieldName) => {
        const optionButton = document.createElement('button');

        optionButton.className =
          'ol-preview-config__declare-part-option ol-preview-config__declare-part-option--config';
        optionButton.type = 'button';
        optionButton.setAttribute('role', 'menuitem');
        optionButton.dataset.previewAction = 'add-missing-config-field';
        optionButton.dataset.configField = fieldName;
        optionButton.textContent = fieldName;
        optionButton.title = `Add ${fieldName}`;

        popup.appendChild(optionButton);
      });

      return popup;
    },

    /** Every supported locale the `Locales` line does not already list. */
    getConfigLocaleOptions(this: any, currentValue = '') {
      const listedLocales = new Set(
        parseConfigLocaleEntries(currentValue)
          .map((localeEntry) => localeEntry.text.toLowerCase())
          .filter(Boolean),
      );

      return CONFIG_LOCALE_VALUES.filter(
        (localeTag) => !listedLocales.has(localeTag.toLowerCase()),
      );
    },

    /**
     * The add-locale picker: a filter field over the supported locales.
     *
     * Unlike Key and Time, the option list is hundreds of tags long, so the
     * field is what makes it usable — it hides non-matching options rather
     * than rebuilding the list, and submitting takes the first still-visible
     * one (type `km`, press Enter).
     */
    populateConfigLocalePopup(this: any, currentValue = '') {
      const popup = this.ensureConfigLocalePopup();
      const localeTags = this.getConfigLocaleOptions(currentValue);
      const form = document.createElement('form');
      const filterInput = document.createElement('input');
      const optionList = document.createElement('div');

      popup.replaceChildren();

      form.className = 'ol-preview-config__locale-form';
      form.noValidate = true;

      filterInput.className = 'ol-preview-config__locale-filter';
      filterInput.type = 'text';
      filterInput.placeholder = 'Filter locales';
      filterInput.autocomplete = 'off';
      filterInput.spellcheck = false;
      filterInput.dataset.previewAction = 'filter-config-locale';
      filterInput.setAttribute('aria-label', 'Filter locales');

      optionList.className = 'ol-preview-config__locale-options';
      optionList.setAttribute('role', 'menu');

      localeTags.forEach((localeTag) => {
        const optionButton = document.createElement('button');

        optionButton.className =
          'ol-preview-config__declare-part-option ol-preview-config__declare-part-option--locale';
        optionButton.type = 'button';
        optionButton.setAttribute('role', 'menuitem');
        optionButton.dataset.previewAction = 'select-config-locale';
        optionButton.dataset.configField = 'Locales';
        optionButton.dataset.configValue = localeTag;
        optionButton.textContent = localeTag;
        optionButton.title = `Add ${localeTag} to Locales`;

        optionList.appendChild(optionButton);
      });

      if (!localeTags.length) {
        const emptyState = document.createElement('p');

        emptyState.className = 'ol-preview-config__declare-part-empty';
        emptyState.textContent = 'Every supported locale is already listed.';
        optionList.appendChild(emptyState);
      }

      form.append(filterInput, optionList);
      popup.append(form);
      return popup;
    },

    getConfigTimeOptions(this: any, currentValue = '') {
      return Array.from(
        new Set(
          [currentValue, ...(CONFIG_ENUM_FIELD_VALUES.Time || [])]
            .map((value) => String(value ?? '').trim())
            .filter(Boolean),
        ),
      );
    },

    getTempoPopupBounds(this: any, currentBpm) {
      return {
        min: Math.min(MIN_TEMPO_BPM, currentBpm || MIN_TEMPO_BPM),
        max: Math.max(MAX_TEMPO_BPM, currentBpm || MAX_TEMPO_BPM),
      };
    },

    populateConfigKeyPopup(this: any, currentValue = '') {
      const popup = this.ensureConfigKeyPopup();
      const options = this.getConfigKeyOptions(currentValue);

      popup.replaceChildren();

      options.forEach((optionValue) => {
        const optionButton = document.createElement('button');
        const isSelected = optionValue === currentValue;

        optionButton.className = `ol-preview-config__declare-part-option ol-preview-config__declare-part-option--key${isSelected ? ' is-selected' : ''}`;
        optionButton.type = 'button';
        optionButton.setAttribute('role', 'menuitemradio');
        optionButton.setAttribute(
          'aria-checked',
          isSelected ? 'true' : 'false',
        );
        optionButton.dataset.previewAction = 'select-config-key';
        optionButton.dataset.configField = 'Key';
        optionButton.dataset.configValue = optionValue;
        optionButton.textContent = optionValue;
        optionButton.title = `Change key to ${optionValue}`;

        popup.appendChild(optionButton);
      });

      return popup;
    },

    populateConfigTimePopup(this: any, currentValue = '') {
      const popup = this.ensureConfigTimePopup();
      const options = this.getConfigTimeOptions(currentValue);

      popup.replaceChildren();

      options.forEach((optionValue) => {
        const optionButton = document.createElement('button');
        const isSelected = optionValue === currentValue;

        optionButton.className = `ol-preview-config__declare-part-option ol-preview-config__declare-part-option--time${isSelected ? ' is-selected' : ''}`;
        optionButton.type = 'button';
        optionButton.setAttribute('role', 'menuitemradio');
        optionButton.setAttribute(
          'aria-checked',
          isSelected ? 'true' : 'false',
        );
        optionButton.dataset.previewAction = 'select-config-time';
        optionButton.dataset.configField = 'Time';
        optionButton.dataset.configValue = optionValue;
        optionButton.textContent = optionValue;
        optionButton.title = `Change time signature to ${optionValue}`;

        popup.appendChild(optionButton);
      });

      return popup;
    },

    populateConfigTempoPopup(this: any, currentValue = '') {
      const popup = this.ensureConfigTempoPopup();
      const currentBpm = this.getTempoBpmValue(currentValue);
      const bounds = this.getTempoPopupBounds(currentBpm);
      const valueShell = document.createElement('div');
      const valueOutput = document.createElement('output');
      const valueSuffix = document.createElement('span');
      const rangeInput = document.createElement('input');
      const scale = document.createElement('div');
      const minLabel = document.createElement('span');
      const maxLabel = document.createElement('span');

      popup.replaceChildren();

      valueShell.className = 'ol-preview-config__tempo-popup-value';
      valueOutput.className = 'ol-preview-config__tempo-popup-output';
      valueOutput.dataset.tempoOutput = 'true';
      valueOutput.value = String(currentBpm);
      valueOutput.textContent = String(currentBpm);
      valueSuffix.className = 'ol-preview-config__tempo-popup-suffix';
      valueSuffix.textContent = 'bpm';
      valueShell.append(valueOutput, valueSuffix);

      rangeInput.className = 'ol-preview-config__tempo-range';
      rangeInput.type = 'range';
      rangeInput.min = String(bounds.min);
      rangeInput.max = String(bounds.max);
      rangeInput.step = '1';
      rangeInput.value = String(currentBpm);
      rangeInput.dataset.previewAction = 'change-config-tempo-range';
      rangeInput.dataset.configField = 'Tempo';
      rangeInput.setAttribute('aria-label', 'Choose tempo');

      scale.className = 'ol-preview-config__tempo-scale';
      minLabel.textContent = String(bounds.min);
      maxLabel.textContent = String(bounds.max);
      scale.append(minLabel, maxLabel);

      popup.append(valueShell, rangeInput, scale);
      return popup;
    },

    showDeclarePartPopup(this: any, triggerButton) {
      const insertIndex = this.getStructureInsertIndex(triggerButton);
      const popup = this.populateDeclarePartPopup(insertIndex);

      if (Number.isInteger(insertIndex)) {
        popup.dataset.structureInsertIndex = String(insertIndex);
      } else {
        delete popup.dataset.structureInsertIndex;
      }

      this.activeDeclarePartButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      const focusTarget =
        popup.querySelector(
          '.ol-preview-config__declare-part-option:not([disabled])',
        ) || popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    showConfigKeyPopup(this: any, triggerButton) {
      const currentValue =
        triggerButton.getAttribute('data-config-current-value') || '';
      const popup = this.populateConfigKeyPopup(currentValue);

      this.activeConfigKeyButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      const focusTarget =
        popup.querySelector('[data-preview-action="select-config-key"]') ||
        popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    showConfigAddPopup(this: any, triggerButton) {
      const rawMissingFields =
        triggerButton.getAttribute('data-config-missing-fields') || '';
      const popup = this.populateConfigAddPopup(rawMissingFields);

      this.activeConfigAddButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      const focusTarget =
        popup.querySelector(
          '[data-preview-action="add-missing-config-field"]',
        ) || popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    showConfigAttachmentPopup(this: any, triggerButton) {
      const popup = this.populateConfigAttachmentPopup();

      this.activeConfigAttachmentButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      const focusTarget =
        popup.querySelector(
          '[data-preview-action="edit-config-attachment-value"]',
        ) || popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    showConfigLocalePopup(this: any, triggerButton) {
      const currentValue =
        triggerButton.getAttribute('data-config-current-value') || '';
      const popup = this.populateConfigLocalePopup(currentValue);

      this.activeConfigLocaleButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      // The filter field is a text-entry control, so `focusElement` may focus
      // it even on a touch-opened iOS popup (see the menu-focus note in
      // `OpenLyricEditorApplication`).
      const focusTarget =
        popup.querySelector('[data-preview-action="filter-config-locale"]') ||
        popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    showConfigTimePopup(this: any, triggerButton) {
      const currentValue =
        triggerButton.getAttribute('data-config-current-value') || '';
      const popup = this.populateConfigTimePopup(currentValue);

      this.activeConfigTimeButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      const focusTarget =
        popup.querySelector('[data-preview-action="select-config-time"]') ||
        popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    showConfigTempoPopup(this: any, triggerButton) {
      const currentValue =
        triggerButton.getAttribute('data-config-current-value') || '';
      const popup = this.populateConfigTempoPopup(currentValue);

      this.activeConfigTempoButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      const focusTarget =
        popup.querySelector(
          '[data-preview-action="change-config-tempo-range"]',
        ) || popup;
      this.focusElement(focusTarget, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    handleDeclarePartPopupClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const declarePartOption = eventTarget?.closest(
        '[data-preview-action="select-structure-part"]',
      );

      if (
        !declarePartOption ||
        !this.isDeclarePartPopupElement(declarePartOption)
      ) {
        return;
      }

      const structureToken =
        declarePartOption.getAttribute('data-structure-token') || '';
      const insertIndex = this.getStructureInsertIndex(this.declarePartPopup);

      event.preventDefault();

      if (!structureToken) {
        return;
      }

      this.closeDeclarePartMenus();
      this.insertStructurePartToken(structureToken, insertIndex);
    },

    handleConfigAddPopupClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const configOption = eventTarget?.closest(
        '[data-preview-action="add-missing-config-field"]',
      );

      if (!configOption || !this.isConfigAddPopupElement(configOption)) {
        return;
      }

      const fieldName = configOption.getAttribute('data-config-field') || '';

      event.preventDefault();

      if (!fieldName) {
        return;
      }

      this.closeDeclarePartMenus();
      this.insertMissingConfigField(fieldName);
    },

    handleConfigKeyPopupClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const keyOption = eventTarget?.closest(
        '[data-preview-action="select-config-key"]',
      );

      if (!keyOption || !this.isConfigKeyPopupElement(keyOption)) {
        return;
      }

      const nextKeyValue = keyOption.getAttribute('data-config-value') || '';

      event.preventDefault();

      if (!nextKeyValue) {
        return;
      }

      this.closeDeclarePartMenus();
      this.updateConfigFieldValue('Key', nextKeyValue);
    },

    handleConfigAttachmentPopupInput(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const input = eventTarget?.closest(
        '[data-preview-action="edit-config-attachment-value"]',
      );

      if (
        !(input instanceof HTMLInputElement) ||
        !this.isConfigAttachmentPopupElement(input)
      ) {
        return;
      }

      const isValid = this.isValidAttachmentConfigValue(input.value);
      const submitButton = this.configAttachmentPopup?.querySelector(
        '.ol-preview-config__attachment-submit',
      );

      input.setAttribute('aria-invalid', isValid ? 'false' : 'true');

      if (submitButton instanceof HTMLButtonElement) {
        submitButton.disabled = !isValid;
      }
    },

    handleConfigAttachmentPopupSubmit(this: any, event) {
      if (!(event.target instanceof HTMLFormElement)) {
        return;
      }

      if (!this.isConfigAttachmentPopupElement(event.target)) {
        return;
      }

      event.preventDefault();

      const input = event.target.querySelector(
        '[data-preview-action="edit-config-attachment-value"]',
      );

      if (!(input instanceof HTMLInputElement)) {
        return;
      }

      const nextValue = this.normalizeAttachmentConfigValue(input.value);
      if (!this.isValidAttachmentConfigValue(nextValue)) {
        input.setAttribute('aria-invalid', 'true');
        input.focus();
        return;
      }

      this.closeDeclarePartMenus();
      this.appendAttachmentValue(nextValue);
    },

    handleConfigLocalePopupClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const localeOption = eventTarget?.closest(
        '[data-preview-action="select-config-locale"]',
      );

      if (!localeOption || !this.isConfigLocalePopupElement(localeOption)) {
        return;
      }

      const nextLocaleValue =
        localeOption.getAttribute('data-config-value') || '';

      event.preventDefault();

      if (!nextLocaleValue) {
        return;
      }

      this.closeDeclarePartMenus();
      this.appendConfigLocale(nextLocaleValue);
    },

    handleConfigLocalePopupInput(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const filterInput = eventTarget?.closest(
        '[data-preview-action="filter-config-locale"]',
      );

      if (
        !(filterInput instanceof HTMLInputElement) ||
        !this.isConfigLocalePopupElement(filterInput)
      ) {
        return;
      }

      this.filterConfigLocaleOptions(filterInput.value);
    },

    filterConfigLocaleOptions(this: any, query) {
      const popup = this.configLocalePopup;

      if (!popup) {
        return [];
      }

      const normalizedQuery = String(query ?? '')
        .trim()
        .toLowerCase();
      const visibleOptions = [];

      popup
        .querySelectorAll('[data-preview-action="select-config-locale"]')
        .forEach((optionButton) => {
          const localeTag = (
            optionButton.getAttribute('data-config-value') || ''
          ).toLowerCase();
          const isMatch =
            !normalizedQuery || localeTag.includes(normalizedQuery);

          optionButton.hidden = !isMatch;

          if (isMatch) {
            visibleOptions.push(optionButton);
          }
        });

      return visibleOptions;
    },

    handleConfigLocalePopupSubmit(this: any, event) {
      if (
        !(event.target instanceof HTMLFormElement) ||
        !this.isConfigLocalePopupElement(event.target)
      ) {
        return;
      }

      event.preventDefault();

      const filterInput = event.target.querySelector(
        '[data-preview-action="filter-config-locale"]',
      );
      const [firstVisibleOption] = this.filterConfigLocaleOptions(
        filterInput instanceof HTMLInputElement ? filterInput.value : '',
      );
      const nextLocaleValue =
        firstVisibleOption?.getAttribute('data-config-value') || '';

      if (!nextLocaleValue) {
        return;
      }

      this.closeDeclarePartMenus();
      this.appendConfigLocale(nextLocaleValue);
    },

    handleConfigTimePopupClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const timeOption = eventTarget?.closest(
        '[data-preview-action="select-config-time"]',
      );

      if (!timeOption || !this.isConfigTimePopupElement(timeOption)) {
        return;
      }

      const nextTimeValue = timeOption.getAttribute('data-config-value') || '';

      event.preventDefault();

      if (!nextTimeValue) {
        return;
      }

      this.closeDeclarePartMenus();
      this.updateConfigFieldValue('Time', nextTimeValue);
    },

    handleConfigTempoPopupInput(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const rangeInput = eventTarget?.closest(
        '[data-preview-action="change-config-tempo-range"]',
      );

      if (
        !(rangeInput instanceof HTMLInputElement) ||
        !this.isConfigTempoPopupElement(rangeInput)
      ) {
        return;
      }

      const valueOutput = this.configTempoPopup?.querySelector(
        '[data-tempo-output]',
      );
      if (valueOutput instanceof HTMLOutputElement) {
        valueOutput.value = rangeInput.value;
        valueOutput.textContent = rangeInput.value;
      }
    },

    handleConfigTempoPopupChange(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const rangeInput = eventTarget?.closest(
        '[data-preview-action="change-config-tempo-range"]',
      );

      if (
        !(rangeInput instanceof HTMLInputElement) ||
        !this.isConfigTempoPopupElement(rangeInput)
      ) {
        return;
      }

      const nextValue = this.normalizeTempoConfigValue(rangeInput.value);

      this.closeDeclarePartMenus();

      if (!nextValue) {
        return;
      }

      this.updateConfigFieldValue('Tempo', nextValue);
    },
  });
}

export { applyPreviewControllerConfigPopupMethods };
