import { isOpenLyricTheme } from '../../editor/components/internal/theme.ts';
import { SVGuitarChord } from 'svguitar';
import {
  createChordDatabaseSearchData,
  createChordDegreeHints,
  normalizeChordText,
} from './domain/music-theory.ts';
import { renderStrummingPatternGrid } from './preview/helpers.ts';

const DEFAULT_TUNING = ['E', 'A', 'D', 'G', 'B', 'E'];
const POPUP_MARGIN_PX = 12;
const POPUP_HIDE_DELAY_MS = 180;
const VARIANT_SIZE_RATIO = 0.3;
const DOCUMENTED_CHORD_DEGREES = ['2', '4', '5', '6', '7', '9', '11', '13'];
const POPUP_TRIGGER_SELECTOR =
  '[data-chord-key], [data-pattern-reference-index]';

const popupState = {
  activeAnchor: null,
  hideTimer: 0,
  pointerDownInside: false,
  pointerInside: false,
  requestToken: 0,
  renderedChordData: null,
  sourceTitle: '',
  suppressFocusOut: false,
  variantIndex: 0,
};

let popupRefs = null;
let guitarChordDatabasePromise = null;

const chordResolutionCache = new Map();

function clearPopupHideTimer() {
  if (!popupState.hideTimer) {
    return;
  }

  clearTimeout(popupState.hideTimer);
  popupState.hideTimer = 0;
}

function handlePopupPointerEnter() {
  popupState.pointerInside = true;
  clearPopupHideTimer();
}

function handlePopupPointerLeave() {
  popupState.pointerInside = false;
  scheduleHideChordDiagramPopup();
}

function handlePopupPointerDown() {
  popupState.pointerDownInside = true;
  popupState.pointerInside = true;
  clearPopupHideTimer();

  window.setTimeout(() => {
    popupState.pointerDownInside = false;
  }, 0);
}

function isChordPopupElement(element) {
  return Boolean(
    element instanceof Element && popupRefs?.popup?.contains(element),
  );
}

function isPopupFocusWithin() {
  return isChordPopupElement(document.activeElement);
}

function handlePopupFocusIn() {
  clearPopupHideTimer();
}

function handlePopupFocusOut(event) {
  if (popupState.suppressFocusOut || popupState.pointerDownInside) {
    return;
  }

  const nextTarget =
    event.relatedTarget instanceof Element ? event.relatedTarget : null;

  if (
    isChordPopupElement(nextTarget) ||
    nextTarget?.closest(POPUP_TRIGGER_SELECTOR)
  ) {
    return;
  }

  hideChordDiagramPopup();
}

function stepPopupVariant(direction) {
  const { variantsTrack } = ensurePopup();
  const variantCount = variantsTrack.childElementCount;

  if (variantCount <= 1) {
    return;
  }

  popupState.variantIndex = Math.max(
    0,
    Math.min(popupState.variantIndex + direction, variantCount - 1),
  );

  updatePopupVariantCarousel();
}

function handleVariantPreviousClick() {
  stepPopupVariant(-1);
}

function handleVariantNextClick() {
  stepPopupVariant(1);
}

function preservePopupFocusBeforeDisablingControls(options) {
  const { disableNext, disablePrevious } = options;
  const { popup, variantsNextButton, variantsPreviousButton } = ensurePopup();
  const activeElement = document.activeElement;

  if (activeElement === variantsNextButton && disableNext) {
    if (!disablePrevious) {
      variantsPreviousButton.focus({ preventScroll: true });
      return;
    }

    popup.focus({ preventScroll: true });
    return;
  }

  if (activeElement === variantsPreviousButton && disablePrevious) {
    if (!disableNext) {
      variantsNextButton.focus({ preventScroll: true });
      return;
    }

    popup.focus({ preventScroll: true });
  }
}

function renderPopupMainChord(chord) {
  if (!chord?.diagramData || !chord?.label) {
    clearPopupDiagram();
    return;
  }

  const { diagram } = ensurePopup();
  setPopupContentType('chord');
  setPopupTooltipText('');
  clearPopupDiagram();
  updatePopupHeader(chord.label, popupState.sourceTitle);

  new SVGuitarChord(diagram)
    .configure(createSvguitarOptions(chord.label))
    .chord(chord.diagramData)
    .draw();
}

function renderPopupPatternPreview(patternData) {
  const patternText = String(patternData?.pattern ?? '').trim();
  if (!patternText) {
    setPopupTooltipText('');
    clearPopupDiagram();
    return;
  }

  const { diagram } = ensurePopup();
  const timeSignatureText =
    String(patternData?.timeSignatureText ?? '').trim() || '4/4';
  const previewWrapper = document.createElement('div');
  previewWrapper.className = 'ol-chord-popup__pattern-preview';

  const gridShell = document.createElement('div');
  gridShell.className = 'ol-chord-popup__pattern-grid-shell';
  gridShell.innerHTML = renderStrummingPatternGrid(
    patternText,
    timeSignatureText,
  );

  previewWrapper.append(gridShell);

  setPopupContentType('pattern');
  setPopupTooltipText(patternText);
  clearPopupDiagram();
  diagram.appendChild(previewWrapper);
}

function previewVariantInMain(variantIndex) {
  const resolvedChordData = popupState.renderedChordData;
  if (!resolvedChordData || !Array.isArray(resolvedChordData.variants)) {
    return;
  }

  const selectedVariant = resolvedChordData.variants[variantIndex];
  if (!selectedVariant) {
    return;
  }

  const previousPrimary = resolvedChordData.primary;
  resolvedChordData.primary = selectedVariant;
  resolvedChordData.variants[variantIndex] = previousPrimary;

  popupState.suppressFocusOut = true;

  renderPopupMainChord(resolvedChordData.primary);
  renderPopupVariants(resolvedChordData.variants, {
    initialIndex: variantIndex,
  });

  const { variantsTrack } = ensurePopup();
  variantsTrack.children[variantIndex]?.focus({ preventScroll: true });

  if (popupState.activeAnchor) {
    positionPopup(popupState.activeAnchor);
  }

  queueMicrotask(() => {
    popupState.suppressFocusOut = false;
  });
}

function ensurePopup() {
  if (popupRefs) {
    return popupRefs;
  }

  const popup = document.createElement('div');
  popup.className = 'ol-chord-popup';
  popup.setAttribute('role', 'tooltip');
  popup.setAttribute('aria-hidden', 'true');
  popup.tabIndex = -1;
  popup.dataset.contentType = 'chord';
  popup.dataset.placement = 'bottom';

  const name = document.createElement('p');
  name.className = 'ol-chord-popup__name';

  const description = document.createElement('p');
  description.className = 'ol-chord-popup__description';

  const header = document.createElement('div');
  header.className = 'ol-chord-popup__header';
  header.append(name, description);

  const diagram = document.createElement('div');
  diagram.className = 'ol-chord-popup__diagram';

  const variantsSection = document.createElement('section');
  variantsSection.className = 'ol-chord-popup__variants';
  variantsSection.hidden = true;

  const variantsHeader = document.createElement('div');
  variantsHeader.className = 'ol-chord-popup__variants-header';

  const variantsHeading = document.createElement('p');
  variantsHeading.className = 'ol-chord-popup__variants-heading';
  variantsHeading.textContent = 'Chord variants';

  const variantsCount = document.createElement('p');
  variantsCount.className = 'ol-chord-popup__variants-count';

  const variantsCarousel = document.createElement('div');
  variantsCarousel.className = 'ol-chord-popup__variants-carousel';

  const variantsPreviousButton = document.createElement('button');
  variantsPreviousButton.className =
    'ol-chord-popup__variants-nav ol-chord-popup__variants-nav--previous';
  variantsPreviousButton.type = 'button';
  variantsPreviousButton.textContent = '<';
  variantsPreviousButton.setAttribute(
    'aria-label',
    'Show previous chord variant',
  );
  variantsPreviousButton.addEventListener('click', handleVariantPreviousClick);

  const variantsViewport = document.createElement('div');
  variantsViewport.className = 'ol-chord-popup__variants-viewport';

  const variantsTrack = document.createElement('div');
  variantsTrack.className = 'ol-chord-popup__variants-track';

  variantsViewport.appendChild(variantsTrack);

  const variantsNextButton = document.createElement('button');
  variantsNextButton.className =
    'ol-chord-popup__variants-nav ol-chord-popup__variants-nav--next';
  variantsNextButton.type = 'button';
  variantsNextButton.textContent = '>';
  variantsNextButton.setAttribute('aria-label', 'Show next chord variant');
  variantsNextButton.addEventListener('click', handleVariantNextClick);

  variantsHeader.append(variantsHeading, variantsCount);
  variantsCarousel.append(
    variantsPreviousButton,
    variantsViewport,
    variantsNextButton,
  );
  variantsSection.append(variantsHeader, variantsCarousel);

  const status = document.createElement('p');
  status.className = 'ol-chord-popup__status';

  popup.addEventListener('mouseenter', handlePopupPointerEnter);
  popup.addEventListener('mouseleave', handlePopupPointerLeave);
  popup.addEventListener('pointerdown', handlePopupPointerDown);
  popup.addEventListener('focusin', handlePopupFocusIn);
  popup.addEventListener('focusout', handlePopupFocusOut);

  popup.append(header, diagram, variantsSection, status);
  document.body.appendChild(popup);

  popupRefs = {
    popup,
    name,
    description,
    diagram,
    variantsSection,
    variantsCount,
    variantsPreviousButton,
    variantsTrack,
    variantsNextButton,
    status,
  };

  return popupRefs;
}

function setPopupVisible(visible) {
  const { popup } = ensurePopup();
  popup.classList.toggle('is-visible', visible);
  popup.setAttribute('aria-hidden', String(!visible));
}

function setPopupContentType(contentType = 'chord') {
  const { popup } = ensurePopup();
  popup.dataset.contentType = contentType;
}

function setPopupTooltipText(text = '') {
  const { popup } = ensurePopup();
  const normalizedText = String(text ?? '').trim();

  if (!normalizedText) {
    popup.removeAttribute('title');
    return;
  }

  popup.setAttribute('title', normalizedText);
}

function positionPopup(anchorElement) {
  const { popup } = ensurePopup();
  const popupRect = popup.getBoundingClientRect();
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;

  let left = POPUP_MARGIN_PX;
  let top = POPUP_MARGIN_PX;
  let placement = 'bottom';
  let pointerX = popupRect.width / 2;

  if (anchorElement instanceof Element) {
    const anchorRect = anchorElement.getBoundingClientRect();
    const belowTop = anchorRect.bottom + POPUP_MARGIN_PX;
    const aboveTop = anchorRect.top - popupRect.height - POPUP_MARGIN_PX;

    left = anchorRect.left + anchorRect.width / 2 - popupRect.width / 2;
    left = Math.max(
      POPUP_MARGIN_PX,
      Math.min(left, viewportWidth - popupRect.width - POPUP_MARGIN_PX),
    );

    if (
      belowTop + popupRect.height <= viewportHeight - POPUP_MARGIN_PX ||
      aboveTop < POPUP_MARGIN_PX
    ) {
      top = Math.min(
        belowTop,
        viewportHeight - popupRect.height - POPUP_MARGIN_PX,
      );
      placement = 'bottom';
    } else {
      top = Math.max(aboveTop, POPUP_MARGIN_PX);
      placement = 'top';
    }

    pointerX = anchorRect.left + anchorRect.width / 2 - left;
    pointerX = Math.max(22, Math.min(pointerX, popupRect.width - 22));
  } else {
    left = Math.max(POPUP_MARGIN_PX, (viewportWidth - popupRect.width) / 2);
    top = POPUP_MARGIN_PX;
  }

  popup.style.left = `${Math.round(left)}px`;
  popup.style.top = `${Math.round(top)}px`;
  popup.dataset.placement = placement;
  popup.style.setProperty(
    '--ol-chord-popup-pointer-x',
    `${Math.round(pointerX)}px`,
  );
}

function normalizePopupTitle(title, chordKey) {
  const normalizedTitle = String(title ?? '')
    .replace(/^Show\s+/i, '')
    .trim();

  return normalizedTitle || chordKey;
}

function updatePopupHeader(chordKey, title) {
  const { name, description } = ensurePopup();
  const normalizedTitle = normalizePopupTitle(title, chordKey);

  name.textContent = chordKey;
  description.textContent = normalizedTitle;
  description.hidden = !normalizedTitle || normalizedTitle === chordKey;
}

function setPopupStatus(message) {
  const { status } = ensurePopup();
  status.textContent = message;
  status.hidden = !message;
}

function clearPopupDiagram() {
  const { diagram } = ensurePopup();
  diagram.replaceChildren();
}

function clearPopupVariants() {
  const {
    variantsCount,
    variantsNextButton,
    variantsPreviousButton,
    variantsSection,
    variantsTrack,
  } = ensurePopup();

  popupState.variantIndex = 0;
  popupState.renderedChordData = null;
  variantsTrack.replaceChildren();
  variantsTrack.style.transform = 'translateX(0%)';
  variantsCount.textContent = '';
  variantsPreviousButton.disabled = true;
  variantsNextButton.disabled = true;
  variantsSection.hidden = true;
}

function updatePopupVariantCarousel(options = {}) {
  const { reposition = true } = options;
  const {
    variantsCount,
    variantsNextButton,
    variantsPreviousButton,
    variantsTrack,
  } = ensurePopup();
  const variantCount = variantsTrack.childElementCount;

  if (!variantCount) {
    popupState.variantIndex = 0;
    variantsTrack.style.transform = 'translateX(0%)';
    variantsCount.textContent = '';
    variantsPreviousButton.disabled = true;
    variantsNextButton.disabled = true;
    return;
  }

  popupState.variantIndex = Math.max(
    0,
    Math.min(popupState.variantIndex, variantCount - 1),
  );

  const disablePrevious = popupState.variantIndex === 0;
  const disableNext = popupState.variantIndex === variantCount - 1;

  preservePopupFocusBeforeDisablingControls({
    disableNext,
    disablePrevious,
  });

  variantsTrack.style.transform = `translateX(-${popupState.variantIndex * 100}%)`;
  variantsCount.textContent = `${popupState.variantIndex + 1} / ${variantCount}`;
  variantsPreviousButton.disabled = disablePrevious;
  variantsNextButton.disabled = disableNext;

  if (reposition && popupState.activeAnchor) {
    positionPopup(popupState.activeAnchor);
  }
}

function loadGuitarChordDatabase() {
  if (guitarChordDatabasePromise) {
    return guitarChordDatabasePromise;
  }

  guitarChordDatabasePromise = import('@tombatossals/chords-db/lib/guitar.json')
    .then((module) => module.default ?? module)
    .catch((error) => {
      guitarChordDatabasePromise = null;
      throw error;
    });

  return guitarChordDatabasePromise;
}

function getLowestPitchClass(position) {
  if (!Array.isArray(position?.midi) || !position.midi.length) {
    return null;
  }

  const lowestMidi = position.midi[0];
  return ((lowestMidi % 12) + 12) % 12;
}

function scorePosition(position) {
  const frets = Array.isArray(position?.frets) ? position.frets : [];
  const openStringCount = frets.filter((fret) => fret === 0).length;
  const mutedStringCount = frets.filter((fret) => fret < 0).length;
  const frettedNotes = frets.filter((fret) => fret > 0);
  const fretSpan = frettedNotes.length
    ? Math.max(...frettedNotes) - Math.min(...frettedNotes)
    : 0;

  return (
    Math.max((position.baseFret || 1) - 1, 0) * 12 +
    (Array.isArray(position?.barres) ? position.barres.length : 0) * 3 +
    fretSpan * 2 +
    frettedNotes.length +
    mutedStringCount * 0.5 -
    openStringCount * 1.5
  );
}

function rankChordPositions(positions, bassPitchClass) {
  if (!Array.isArray(positions) || !positions.length) {
    return [];
  }

  return positions
    .map((position, index) => ({
      bassMatches:
        typeof bassPitchClass === 'number'
          ? getLowestPitchClass(position) === bassPitchClass
          : false,
      index,
      position,
      score: scorePosition(position),
    }))
    .sort((left, right) => {
      if (left.bassMatches !== right.bassMatches) {
        return Number(right.bassMatches) - Number(left.bassMatches);
      }

      if (left.score !== right.score) {
        return left.score - right.score;
      }

      return left.index - right.index;
    })
    .map((entry) => entry.position);
}

function deriveBarres(position) {
  const frets = Array.isArray(position?.frets) ? position.frets : [];
  const fingers = Array.isArray(position?.fingers) ? position.fingers : [];
  const barres = Array.isArray(position?.barres) ? position.barres : [];

  return barres
    .map((barreFret) => {
      const matchingEntries = frets
        .map((fret, index) => ({
          fret,
          index,
          finger: fingers[index] || 0,
        }))
        .filter((entry) => entry.fret === barreFret);

      if (!matchingEntries.length) {
        return null;
      }

      const targetFinger =
        matchingEntries.find((entry) => entry.finger > 0)?.finger || 0;
      const filteredEntries = targetFinger
        ? matchingEntries.filter((entry) => entry.finger === targetFinger)
        : matchingEntries;
      const fromIndex = filteredEntries[0]?.index;
      const toIndex = filteredEntries[filteredEntries.length - 1]?.index;

      if (
        typeof fromIndex !== 'number' ||
        typeof toIndex !== 'number' ||
        fromIndex === toIndex
      ) {
        return null;
      }

      const barreFinger = targetFinger > 0 ? String(targetFinger) : undefined;

      return {
        fromString: 6 - fromIndex,
        toString: 6 - toIndex,
        fret: barreFret,
        style: 'arc',
        text: barreFinger,
      };
    })
    .filter(Boolean);
}

function createSvguitarData(position) {
  const fingers = [];

  for (const [index, fret] of (position?.frets || []).entries()) {
    const stringNumber = 6 - index;
    const fingerNumber = position?.fingers?.[index] || 0;

    if (fret < 0) {
      fingers.push([stringNumber, 'x']);
      continue;
    }

    if (fret === 0) {
      fingers.push([stringNumber, 0]);
      continue;
    }

    fingers.push([
      stringNumber,
      fret,
      fingerNumber > 0 ? String(fingerNumber) : undefined,
    ]);
  }

  return {
    fingers,
    position: Math.max(position?.baseFret || 1, 1),
    barres: deriveBarres(position),
  };
}

function resolveMatchingChordEntry(database, parsedChord) {
  const chordEntries = database?.chords?.[parsedChord.datasetRoot];
  if (!Array.isArray(chordEntries) || !chordEntries.length) {
    return null;
  }

  for (const suffixCandidate of parsedChord.suffixCandidates) {
    const matchingEntry = chordEntries.find(
      (entry) => entry.suffix === suffixCandidate,
    );

    if (matchingEntry) {
      return matchingEntry;
    }
  }

  return chordEntries.find((entry) => entry.suffix === 'major') || null;
}

function buildChordVariantKey(root, suffix, bassRoot = '') {
  const chordKey = `${root}${suffix}`;
  return bassRoot ? `${chordKey}/${bassRoot}` : chordKey;
}

function createDocumentedVariantSuffixes() {
  const suffixes = [];

  function push(value) {
    if (suffixes.includes(value)) {
      return;
    }

    suffixes.push(value);
  }

  push('');
  push('m');
  DOCUMENTED_CHORD_DEGREES.forEach((degree) => push(`m${degree}`));
  push('maj');
  DOCUMENTED_CHORD_DEGREES.forEach((degree) => push(`maj${degree}`));
  DOCUMENTED_CHORD_DEGREES.forEach((degree) => push(degree));
  push('sus2');
  push('sus4');
  DOCUMENTED_CHORD_DEGREES.forEach((degree) => push(`add${degree}`));
  push('no3');
  push('omit5');
  push('dim');
  DOCUMENTED_CHORD_DEGREES.forEach((degree) => push(`dim${degree}`));
  push('aug');
  DOCUMENTED_CHORD_DEGREES.forEach((degree) => push(`aug${degree}`));
  push('m7b5');

  return suffixes;
}

function createDocumentedVariantChordKeys(resolvedChord) {
  const { bassRoot = '', root } = resolvedChord.parsedChord;
  const chordKeys = [];

  function pushSuffix(suffix) {
    const chordKey = buildChordVariantKey(root, suffix, bassRoot);
    if (!chordKeys.includes(chordKey)) {
      chordKeys.push(chordKey);
    }
  }

  createDocumentedVariantSuffixes().forEach(pushSuffix);

  createChordDegreeHints(resolvedChord.parsedChord.normalizedChordKey)
    .slice()
    .reverse()
    .forEach((degreeHint) => {
      [
        degreeHint,
        `m${degreeHint}`,
        `maj${degreeHint}`,
        `add${degreeHint}`,
        `dim${degreeHint}`,
        `aug${degreeHint}`,
      ]
        .reverse()
        .forEach((suffix) => {
          const chordKey = buildChordVariantKey(root, suffix, bassRoot);
          const chordKeyIndex = chordKeys.indexOf(chordKey);
          if (chordKeyIndex > 0) {
            chordKeys.splice(chordKeyIndex, 1);
            chordKeys.unshift(chordKey);
          }
        });
    });

  return chordKeys;
}

function createResolvedChordFamilyId(resolvedChord) {
  return [
    resolvedChord.parsedChord.datasetRoot,
    resolvedChord.matchedSuffix,
    resolvedChord.parsedChord.bassPitchClass ?? '',
  ].join('|');
}

function resolveChordDiagramEntry(database, chordKey) {
  const normalizedChordKey = normalizeChordText(chordKey);
  const parsedChord = createChordDatabaseSearchData(normalizedChordKey);
  if (!parsedChord) {
    return null;
  }

  const matchingEntry = resolveMatchingChordEntry(database, parsedChord);
  if (!matchingEntry) {
    return null;
  }

  const rankedPositions = rankChordPositions(
    matchingEntry.positions,
    parsedChord.bassPitchClass,
  );
  if (!rankedPositions.length) {
    return null;
  }

  return {
    chordKey,
    diagramData: createSvguitarData(rankedPositions[0]),
    label: parsedChord.normalizedChordKey,
    matchedSuffix: matchingEntry.suffix,
    parsedChord,
  };
}

function resolveChordDiagramData(database, chordKey) {
  const normalizedChordKey = normalizeChordText(chordKey);

  if (chordResolutionCache.has(normalizedChordKey)) {
    return chordResolutionCache.get(normalizedChordKey);
  }

  const primaryChord = resolveChordDiagramEntry(database, normalizedChordKey);
  if (!primaryChord) {
    chordResolutionCache.set(normalizedChordKey, null);
    return null;
  }

  const seenFamilyIds = new Set([createResolvedChordFamilyId(primaryChord)]);
  const variants = [];

  for (const variantChordKey of createDocumentedVariantChordKeys(
    primaryChord,
  )) {
    const variantChord = resolveChordDiagramEntry(database, variantChordKey);
    if (!variantChord) {
      continue;
    }

    const variantFamilyId = createResolvedChordFamilyId(variantChord);
    if (seenFamilyIds.has(variantFamilyId)) {
      continue;
    }

    seenFamilyIds.add(variantFamilyId);
    variants.push({
      diagramData: variantChord.diagramData,
      label: variantChord.label,
    });
  }

  const resolvedData = {
    primary: {
      label: primaryChord.label,
      diagramData: primaryChord.diagramData,
    },
    variants,
  };
  chordResolutionCache.set(normalizedChordKey, resolvedData);
  return resolvedData;
}

/**
 * Resolve a theme token for the drawn chord diagram. Read from the popup
 * element rather than `<html>`: the popup mirrors the theme of the surface that
 * opened it (see `syncPopupThemeToTrigger`), so a standalone embed whose theme
 * differs from the host page still draws a matching diagram. On the app pages
 * the popup inherits the page tokens, so this resolves to the same values.
 */
function getThemeColor(variableName, fallback) {
  const source = popupRefs?.popup ?? document.documentElement;

  return (
    getComputedStyle(source).getPropertyValue(variableName).trim() || fallback
  );
}

function createSvguitarOptions(chordKey, options = {}) {
  const { compact = false } = options;
  const scale = compact ? VARIANT_SIZE_RATIO : 1;

  return {
    strings: DEFAULT_TUNING.length,
    frets: 5,
    tuning: DEFAULT_TUNING.map(() => ''),
    tuningsFontSize: 1,
    fretLabelFontSize: 18 * scale,
    fingerTextSize: 15 * scale,
    fingerSize: 0.72 * scale,
    sidePadding: 0.16 * scale,
    strokeWidth: 1.6 * scale,
    backgroundColor: getThemeColor('--chord-popup-diagram-surface', '#ffffff'),
    color: getThemeColor('--chord-popup-diagram-ink', '#213547'),
    fretColor: getThemeColor('--chord-popup-diagram-line', '#52606d'),
    stringColor: getThemeColor('--chord-popup-diagram-line', '#52606d'),
    fretLabelColor: getThemeColor('--chord-popup-diagram-label', '#52606d'),
    tuningsColor: getThemeColor('--chord-popup-diagram-label', '#52606d'),
    fingerColor: getThemeColor('--accent', '#115e59'),
    fingerStrokeColor: getThemeColor('--accent', '#115e59'),
    fingerTextColor: getThemeColor('--surface', '#ffffff'),
    barreChordStyle: 'arc',
    barreChordStrokeWidth: 0,
    title: '',
    titleBottomMargin: 0,
    svgTitle: `${compact ? 'Alternate ' : ''}guitar chord diagram for ${chordKey}`,
  };
}

function renderPopupVariants(variants, options = {}) {
  const { initialIndex = 0 } = options;
  const { variantsSection, variantsTrack } = ensurePopup();
  variantsTrack.replaceChildren();

  if (!Array.isArray(variants) || !variants.length) {
    popupState.variantIndex = 0;
    variantsSection.hidden = true;
    updatePopupVariantCarousel({ reposition: false });
    return;
  }

  const fragment = document.createDocumentFragment();
  const variantEntries = [];

  for (const [index, variant] of variants.entries()) {
    const variantCard = document.createElement('button');
    variantCard.className = 'ol-chord-popup__variant';
    variantCard.type = 'button';
    variantCard.setAttribute(
      'aria-label',
      `Preview ${variant.label} in the main chord diagram`,
    );
    variantCard.addEventListener('click', () => {
      previewVariantInMain(index);
    });

    const variantDiagram = document.createElement('div');
    variantDiagram.className = 'ol-chord-popup__variant-diagram';

    const variantLabel = document.createElement('span');
    variantLabel.className = 'ol-chord-popup__variant-label';
    variantLabel.textContent = variant.label;

    variantCard.append(variantDiagram, variantLabel);
    fragment.appendChild(variantCard);
    variantEntries.push({
      diagramData: variant.diagramData,
      label: variant.label,
      variantDiagram,
    });
  }

  popupState.variantIndex = initialIndex;
  variantsTrack.appendChild(fragment);
  variantsSection.hidden = false;

  for (const variantEntry of variantEntries) {
    new SVGuitarChord(variantEntry.variantDiagram)
      .configure(createSvguitarOptions(variantEntry.label, { compact: true }))
      .chord(variantEntry.diagramData)
      .draw();
  }

  updatePopupVariantCarousel({ reposition: false });
}

async function showChordDiagramPopup(
  chordKey,
  anchorElement = null,
  options = {},
) {
  const normalizedChordKey = normalizeChordText(chordKey);

  if (!normalizedChordKey) {
    hideChordDiagramPopup();
    return;
  }

  popupState.activeAnchor =
    anchorElement instanceof Element ? anchorElement : null;
  const requestToken = ++popupState.requestToken;

  clearPopupHideTimer();

  popupState.sourceTitle = options.title || '';
  popupState.renderedChordData = null;
  setPopupContentType('chord');
  updatePopupHeader(normalizedChordKey, options.title);
  clearPopupDiagram();
  clearPopupVariants();
  setPopupStatus('Loading guitar diagram...');
  setPopupVisible(true);
  positionPopup(popupState.activeAnchor);

  try {
    const database = await loadGuitarChordDatabase();

    if (requestToken !== popupState.requestToken) {
      return;
    }

    const chordData = resolveChordDiagramData(database, normalizedChordKey);
    if (!chordData) {
      clearPopupDiagram();
      clearPopupVariants();
      setPopupStatus('No guitar diagram available for this chord.');
      positionPopup(popupState.activeAnchor);
      return;
    }

    clearPopupDiagram();
    clearPopupVariants();
    setPopupStatus('');

    popupState.renderedChordData = {
      primary: chordData.primary,
      variants: [...chordData.variants],
    };

    renderPopupMainChord(popupState.renderedChordData.primary);
    renderPopupVariants(popupState.renderedChordData.variants);
    positionPopup(popupState.activeAnchor);
  } catch (error) {
    if (requestToken !== popupState.requestToken) {
      return;
    }

    console.error('Failed to render chord diagram', error);
    clearPopupDiagram();
    clearPopupVariants();
    setPopupStatus('Unable to load the chord diagram.');
    positionPopup(popupState.activeAnchor);
  }
}

function showPatternPreviewPopup(patternData, anchorElement = null) {
  const patternText = String(patternData?.pattern ?? '').trim();

  if (!patternText) {
    hideChordDiagramPopup();
    return;
  }

  popupState.activeAnchor =
    anchorElement instanceof Element ? anchorElement : null;
  popupState.requestToken += 1;

  clearPopupHideTimer();

  popupState.sourceTitle = '';
  popupState.renderedChordData = null;

  const referenceIndex = Number.isInteger(patternData?.referenceIndex)
    ? patternData.referenceIndex
    : null;
  const popupName = referenceIndex
    ? `Pattern ${referenceIndex}`
    : 'Strumming Pattern';
  const popupDescription = String(patternData?.label ?? '').trim();

  updatePopupHeader(popupName, popupDescription);
  clearPopupVariants();
  setPopupStatus('');
  renderPopupPatternPreview({
    pattern: patternText,
    timeSignatureText: patternData?.timeSignatureText,
  });
  setPopupVisible(true);
  positionPopup(popupState.activeAnchor);
}

function showChordDiagramPopupForElement(element) {
  if (!(element instanceof Element)) {
    return;
  }

  const chordKey = element.getAttribute('data-chord-key');
  if (!chordKey) {
    return;
  }

  showChordDiagramPopup(chordKey, element, {
    title: element.getAttribute('data-chord-title') || '',
  });
}

function showPatternPreviewPopupForElement(element) {
  if (!(element instanceof Element)) {
    return;
  }

  const patternText = element.getAttribute('data-pattern-reference-source');
  if (!patternText) {
    return;
  }

  const patternIndexText =
    element.getAttribute('data-pattern-reference-index') || '';
  const patternIndex = Number.parseInt(patternIndexText, 10);

  showPatternPreviewPopup(
    {
      label: element.getAttribute('data-pattern-reference-label') || '',
      pattern: patternText,
      referenceIndex: Number.isInteger(patternIndex) ? patternIndex : null,
      timeSignatureText:
        element.getAttribute('data-pattern-preview-time') || '4/4',
    },
    element,
  );
}

/**
 * Mirror the theme of the surface that opened the popup onto the popup itself.
 * The popup is appended to `document.body`, outside every component container,
 * so it would otherwise follow the page's `<html data-theme>` alone — wrong for
 * a standalone embed whose own `[data-ol-theme]` marker disagrees with the host
 * page (a light preview on a dark page would pop a dark card). With no marker
 * above the trigger the attribute is dropped and the page theme applies, which
 * is what the app pages want.
 */
function syncPopupThemeToTrigger(element) {
  const { popup } = ensurePopup();
  const theme = element
    .closest('[data-ol-theme]')
    ?.getAttribute('data-ol-theme');

  if (isOpenLyricTheme(theme)) {
    popup.setAttribute('data-ol-theme', theme);
    return;
  }

  popup.removeAttribute('data-ol-theme');
}

function showPreviewPopupForElement(element) {
  if (!(element instanceof Element)) {
    return;
  }

  syncPopupThemeToTrigger(element);

  if (element.hasAttribute('data-chord-key')) {
    showChordDiagramPopupForElement(element);
    return;
  }

  if (element.hasAttribute('data-pattern-reference-index')) {
    showPatternPreviewPopupForElement(element);
  }
}

function scheduleHideChordDiagramPopup(delay = POPUP_HIDE_DELAY_MS) {
  clearPopupHideTimer();

  popupState.hideTimer = window.setTimeout(() => {
    popupState.hideTimer = 0;

    if (popupState.pointerInside || isPopupFocusWithin()) {
      return;
    }

    hideChordDiagramPopup();
  }, delay);
}

function hideChordDiagramPopup() {
  clearPopupHideTimer();
  popupState.activeAnchor = null;
  popupState.pointerDownInside = false;
  popupState.pointerInside = false;
  popupState.requestToken += 1;

  if (!popupRefs) {
    return;
  }

  setPopupVisible(false);
}

export {
  hideChordDiagramPopup,
  isChordPopupElement,
  scheduleHideChordDiagramPopup,
  showChordDiagramPopup,
  showChordDiagramPopupForElement,
  showPreviewPopupForElement,
};
