/**
 * Viewport-anchored positioning for the chrome's dropdown panels.
 *
 * Every popup panel the editor opens — the preview settings popup, the `⋮`
 * options menus, the topbar actions menu, the topbar info disclosure — used to
 * be `position: absolute` inside the wrapper that holds its trigger. That is
 * fine on our own pages, where the wrapper's panel is tall enough, but it makes
 * the panel a hostage of every ancestor's `overflow`: embed an `Editor` or an
 * `OpenLyric` preview in a host UI whose column scrolls or clips, and the menu
 * is cut off at the container edge instead of floating over it.
 *
 * So the panels are `position: fixed` and this module places them: measure the
 * trigger, place the panel just below it (flipping above when the space below
 * is both too small and smaller than the space above), clamp into the viewport,
 * and cap `max-height` to the room actually available so a long menu scrolls
 * rather than running off-screen.
 *
 * `openFloatingMenu()` also keeps the panel glued to its trigger while it is
 * open — a page scroll, a window resize, or a panel drag-resize repositions it
 * instead of leaving it stranded (a fixed box does not scroll with its anchor).
 *
 * The same shape as `positionDeclarePartPopup()` in the Open Lyric preview's
 * `config-popups.ts`, which has always positioned its body-level popups this
 * way; these panels stay in their wrapper (so the `contains()`-based focusout
 * and outside-pointerdown checks still see them) and only borrow the geometry.
 *
 * ## The `position: fixed` escape hatch has one requirement
 *
 * A fixed box escapes ancestor clipping only while no ancestor establishes a
 * containing block for it — `transform`, `filter`, `backdrop-filter`,
 * `perspective`, `will-change`, `contain: layout|paint`, and `container-type`
 * all do. Our own chrome is kept clear of those on the menus' ancestors (see
 * the note on `.preview-panel__body--floating-tools` in
 * `_preview-panel-chrome.scss`); a host page that wraps an embed in a
 * transformed element is beyond what CSS can rescue.
 */

/** Gap kept between a panel and the viewport edge. */
const FLOATING_MENU_MARGIN_PX = 8;
/** Gap between a panel and the trigger it hangs off. */
const FLOATING_MENU_OFFSET_PX = 6;

/**
 * `'end'` pins the panel's right edge to the anchor's right edge (the default —
 * these triggers sit at the right of their toolbars), `'start'` its left edge
 * to the anchor's left edge.
 */
type FloatingMenuAlign = 'start' | 'end';

interface FloatingMenuOptions {
  align?: FloatingMenuAlign;
  offsetPx?: number;
  marginPx?: number;
}

interface TrackedFloatingMenu {
  anchor: HTMLElement;
  options: FloatingMenuOptions;
  resizeObserver: ResizeObserver | null;
}

const trackedFloatingMenus = new Map<HTMLElement, TrackedFloatingMenu>();
let viewportListenersAttached = false;

function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(value, max));
}

/**
 * Whether the panel is actually floating right now.
 *
 * The stylesheet — not this module — decides: `.topbar-meta__content` is only
 * `position: fixed` in the stacked (mobile) layout, and an embed that failed to
 * load our stylesheet gets no inline geometry rather than a panel pinned to the
 * top-left corner.
 */
function isFloatingMenu(menu: Element) {
  if (!(menu instanceof HTMLElement) || !menu.isConnected) {
    return false;
  }

  const view = menu.ownerDocument?.defaultView;

  return view?.getComputedStyle(menu).position === 'fixed';
}

/** Drop the geometry so the panel measures naturally the next time it opens. */
function clearFloatingMenuPosition(menu: Element | null | undefined) {
  if (!(menu instanceof HTMLElement)) {
    return;
  }

  menu.style.removeProperty('left');
  menu.style.removeProperty('top');
  menu.style.removeProperty('max-width');
  menu.style.removeProperty('max-height');
}

/**
 * Place `menu` against `anchor` in viewport coordinates.
 *
 * The panel must already be visible (`hidden = false`) — it is measured, so an
 * unrendered box would report a zero rect. Returns whether geometry was
 * written.
 */
function positionFloatingMenu(
  menu: Element | null | undefined,
  anchor: Element | null | undefined,
  options: FloatingMenuOptions = {},
) {
  if (
    !(menu instanceof HTMLElement) ||
    !(anchor instanceof HTMLElement) ||
    !anchor.isConnected ||
    menu.hidden
  ) {
    return false;
  }

  if (!isFloatingMenu(menu)) {
    clearFloatingMenuPosition(menu);
    return false;
  }

  const view = menu.ownerDocument.defaultView;
  const margin = options.marginPx ?? FLOATING_MENU_MARGIN_PX;
  const offset = options.offsetPx ?? FLOATING_MENU_OFFSET_PX;
  const viewportWidth =
    menu.ownerDocument.documentElement.clientWidth || view?.innerWidth || 0;
  const viewportHeight =
    menu.ownerDocument.documentElement.clientHeight || view?.innerHeight || 0;

  // Measure at a known spot with only the viewport width constraining it, so
  // the rect reflects the panel's natural size rather than the last placement.
  menu.style.removeProperty('max-height');
  menu.style.maxWidth = `${Math.max(viewportWidth - margin * 2, 0)}px`;
  menu.style.left = `${margin}px`;
  menu.style.top = `${margin}px`;

  const anchorRect = anchor.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  // What `left: 8px` actually resolved to on screen. Usually 8 — but a fixed
  // box is positioned against its *containing block*, and any ancestor with a
  // transform, filter, or `backdrop-filter` becomes one (the dashboard topbar
  // is frosted, so its menu is a real case). Correcting by the measured delta
  // keeps the placement below in honest viewport coordinates either way.
  const containingBlockLeft = menuRect.left - margin;
  const containingBlockTop = menuRect.top - margin;
  const spaceBelow = viewportHeight - anchorRect.bottom - offset - margin;
  const spaceAbove = anchorRect.top - offset - margin;
  // Flip above only when below cannot hold the panel *and* above holds more of
  // it — a panel taller than either side stays below, where it reads first.
  const placeAbove = menuRect.height > spaceBelow && spaceAbove > spaceBelow;
  const available = Math.max(placeAbove ? spaceAbove : spaceBelow, 0);

  if (menuRect.height > available) {
    menu.style.maxHeight = `${Math.floor(available)}px`;
  }

  const height = Math.min(menuRect.height, available);
  const left =
    options.align === 'start'
      ? anchorRect.left
      : anchorRect.right - menuRect.width;
  const top = placeAbove
    ? anchorRect.top - offset - height
    : anchorRect.bottom + offset;

  const viewportLeft = clamp(
    left,
    margin,
    Math.max(viewportWidth - menuRect.width - margin, margin),
  );
  const viewportTop = clamp(
    top,
    margin,
    Math.max(viewportHeight - height - margin, margin),
  );

  menu.style.left = `${Math.round(viewportLeft - containingBlockLeft)}px`;
  menu.style.top = `${Math.round(viewportTop - containingBlockTop)}px`;

  return true;
}

/** Re-place every panel currently open, dropping any that left the document. */
function repositionOpenFloatingMenus() {
  trackedFloatingMenus.forEach((tracked, menu) => {
    if (!menu.isConnected || menu.hidden) {
      closeFloatingMenu(menu);
      return;
    }

    positionFloatingMenu(menu, tracked.anchor, tracked.options);
  });
}

function ensureViewportListeners(view: (Window & typeof globalThis) | null) {
  if (viewportListenersAttached || !view) {
    return;
  }

  viewportListenersAttached = true;
  // Capture, so a scroll inside any panel body counts too — scroll events from
  // a nested scroller do not bubble to the window.
  view.addEventListener('scroll', repositionOpenFloatingMenus, {
    capture: true,
    passive: true,
  });
  view.addEventListener('resize', repositionOpenFloatingMenus, {
    passive: true,
  });
}

/**
 * Position `menu` against `anchor` and keep it there until
 * `closeFloatingMenu()`.
 *
 * Call it *after* revealing the panel (`menu.hidden = false`), and pair every
 * call with `closeFloatingMenu()` in the matching close path.
 */
function openFloatingMenu(
  menu: Element | null | undefined,
  anchor: Element | null | undefined,
  options: FloatingMenuOptions = {},
) {
  if (!(menu instanceof HTMLElement) || !(anchor instanceof HTMLElement)) {
    return false;
  }

  const positioned = positionFloatingMenu(menu, anchor, options);

  if (!positioned) {
    return false;
  }

  closeFloatingMenu(menu, { keepPosition: true });

  const view = menu.ownerDocument.defaultView;
  // A panel drag-resize or a wrapping toolbar moves the anchor without any
  // scroll or window resize, so watch the anchor's own box as well.
  const resizeObserver =
    typeof view?.ResizeObserver === 'function'
      ? new view.ResizeObserver(() => repositionOpenFloatingMenus())
      : null;

  resizeObserver?.observe(anchor);
  trackedFloatingMenus.set(menu, { anchor, options, resizeObserver });
  ensureViewportListeners(view ?? null);

  return true;
}

/** Stop tracking `menu` and (unless told otherwise) drop its geometry. */
function closeFloatingMenu(
  menu: Element | null | undefined,
  options: { keepPosition?: boolean } = {},
) {
  if (!(menu instanceof HTMLElement)) {
    return;
  }

  trackedFloatingMenus.get(menu)?.resizeObserver?.disconnect();
  trackedFloatingMenus.delete(menu);

  if (!options.keepPosition) {
    clearFloatingMenuPosition(menu);
  }
}

export {
  FLOATING_MENU_MARGIN_PX,
  FLOATING_MENU_OFFSET_PX,
  clearFloatingMenuPosition,
  closeFloatingMenu,
  isFloatingMenu,
  openFloatingMenu,
  positionFloatingMenu,
  repositionOpenFloatingMenus,
};
export type { FloatingMenuAlign, FloatingMenuOptions };
